import React from 'react';
import styled from 'styled-components';
import TopImage from '../images/forest.jpg';
import { Col, Row } from 'react-styled-flexboxgrid';
import Timeline from '../components/Timeline';
import Skills from '../components/Skills';
import { Footer, FooterInfo } from '../components/Footer';
import Header from '../components/Header.jsx';
import ContentsArea from '../components/ContentsArea';
import StyledGrid from '../components/atoms/StyledGrid';
import Form from '../components/Form';
import Hiro from '../images/hiro.jpeg';
import GlobalCss from '../components/GlobalCss';
import Work from '../components/Work';
import media from 'styled-media-query';
import Seo from '../components/seo.js';
import { getImage } from 'gatsby-plugin-image';
import { graphql } from 'gatsby';

const TopPage = ({ data }) => {
  const image = getImage(
    data.allFile.edges[0].node.childImageSharp.gatsbyImageData
  );
  return (
    <div>
      <Seo
        title="TAKAHIRO SAEKIのポートフォリオサイト"
        description="三枝木貴浩のポートフォリオサイト"
        image={image.images.fallback.src}
      />
      <Header title="TAKAHIRO SAEKI" path="/" />
      <GlobalCss />
      <ImgWrap>
        <BgCover>
          <IntroArea />
        </BgCover>
      </ImgWrap>
      <ContentsArea />
      <StyledGrid fluid>
        <Skills />
      </StyledGrid>
      <Work />
      <ExtendStyledGrid fluid>
        <StyledRow>
          <StyledCol xs={12}>
            <HeaderWrap>
              <h2>タイムライン</h2>
            </HeaderWrap>
          </StyledCol>
          <Timeline />
        </StyledRow>
        <Form />
        <FooterInfo />
      </ExtendStyledGrid>
      <Footer />
    </div>
  );
};

const StyledCol = styled(Col)`
  ${media.lessThan('medium')`
padding: 0;
`}
`;

const StyledRow = styled(Row)`
  ${media.lessThan('medium')`
padding: 0;
`}
`;

const ExtendStyledGrid = styled(StyledGrid)`
  ${media.lessThan('medium')`
  padding: 4px;
`}
`;

const BgCover = styled.div`
  background: rgba(51, 51, 51, 0.5);
  width: 100%;
  height: 100%;
`;

const IntroArea = () => (
  <IntroAreaWrap>
    <div>
      <img src={Hiro} alt="TAKAHIRO SAEKI" />
    </div>
    <div>Takahiro Saeki</div>
    <div>frontend developer</div>
  </IntroAreaWrap>
);

const IntroAreaWrap = styled.div`
  top: 0;
  right: 0;
  left: 0;
  bottom: 0;
  width: 180px;
  height: 180px;
  margin: auto;
  position: absolute;
  color: #fff;
  img {
    border-radius: 50%;
  }
`;

const ImgWrap = styled.div`
  background-image: url(${TopImage});
  background-position: center center;
  background-repeat: no-repeat;
  background-size: cover;
  background-color: rgb(70, 70, 70);
  position: relative;
  height: 700px;

  ${media.lessThan('medium')`
  height: 500px;
  `}
`;

const HeaderWrap = styled.div`
  h2 {
    margin: auto;
    text-align: center;
    padding-bottom: 16px;
  }
`;

export default TopPage;

export const pageQuery = graphql`
  query portfolioData {
    allFile(filter: { name: { eq: "ts" } }) {
      edges {
        node {
          id
          name
          childImageSharp {
            gatsbyImageData
          }
        }
      }
    }
  }
`;
